// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _caller, address _newOwner) public {
        vm.assume(_caller == c.owner());
        address oldOwner = c.owner();
        vm.prank(_caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, _newOwner));
        assertTrue(!success || c.owner() == oldOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        address originalOwner = c.owner();
        vm.assume(msg.sender == originalOwner);
        vm.prank(msg.sender);
        bool success = c.setOwner(newOwner);
        assertTrue(success && c.owner() == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        c.setOwner(caller);
        assertTrue(c.owner() == caller);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address initialOwner;

    function setUp() public { 
        c = new C();
        initialOwner = c.owner();
    }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != initialOwner);
        vm.assume(newOwner != address(0));

        vm.prank(caller);
        c.setOwner(newOwner);

        assertTrue(c.owner() == initialOwner);
    }
}
